css:
.cat-btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;height:var(--cat-size-control-h-md);padding:0 14px;border-radius:var(--cat-size-radius-sm);border:1px solid transparent;font:500 var(--cat-font-size-base)/1 var(--cat-font-family-ui);cursor:pointer;text-decoration:none;transition:background var(--cat-motion-fast) var(--cat-motion-ease-out),filter var(--cat-motion-fast) ease,transform var(--cat-motion-fast) var(--cat-motion-ease-out),box-shadow var(--cat-motion-med) ease}
.cat-btn:focus-visible{outline:none;box-shadow:0 0 0 var(--cat-size-border-focus-ring) var(--cat-semantic-accent-ring)}
.cat-btn:active{transform:scale(.97)}
.cat-btn:disabled,.cat-btn.disabled{opacity:.45;cursor:default;pointer-events:none}
.cat-btn.primary{background:var(--cat-semantic-accent-dynamic,var(--cat-color-accent-base));color:#fff;box-shadow:none}
.cat-btn.primary:hover{background:var(--cat-color-accent-hover)}
.cat-btn.primary:active{background:var(--cat-color-accent-active)}
.cat-btn.secondary{color:var(--cat-color-ink-hi);background:var(--cat-semantic-chip-a);border-color:var(--cat-color-stroke-light);box-shadow:var(--cat-elevation-chip-hover)}
.cat-btn.secondary:hover{background:var(--cat-semantic-chip-hover-a)}
.cat-btn.ghost{background:transparent;color:var(--cat-color-ink-mid)}
.cat-btn.ghost:hover{background:var(--cat-color-surface-hover);color:var(--cat-color-ink-hi)}
.cat-btn.danger{background:var(--cat-color-danger-base);color:#fff;box-shadow:none}
.cat-btn.danger:hover{background:var(--cat-color-danger-hover)}
.cat-btn.link{height:auto;padding:0;background:none;color:var(--cat-color-accent-base)}
.cat-btn.link:hover{text-decoration:underline}
.cat-btn.sm{height:var(--cat-size-control-h-sm);padding:0 10px;font-size:var(--cat-font-size-sm)}
.cat-btn.lg{height:var(--cat-size-control-h-lg);padding:0 18px;font-size:var(--cat-font-size-lg)}
.cat-btn .cat-icon{width:var(--cat-size-icon-md);height:var(--cat-size-icon-md)}
